// import type { ComponentStyleVariantConfig, Theme } from "@types";
import type { AIMessageProps, AIMessageListProps } from "./ai-message.types";

import { type CSSObject } from "@emotion/react";
import styled from "@emotion/styled";
import { getExcludedDOMProps, getStyleSlots } from "@system";

// --- AIMessage ---

// Make sure component name matches its type in the ThemeComponentVariants
const messageComponentName = "AIMessage";

// Generate child element class names for the component, should match available style slots
export const AIMessageClasses = {
  root: "exp-textura_ai_message",
  messageUser: "exp-textura_ai_message_user",
  messageAssistant: "exp-textura_ai_message_assistant",
  markdown: "exp-textura_ai_markdown",
  plainText: "exp-textura_ai_plain_text",
};

const generateMessageStyles = (props: AIMessageProps): CSSObject => {
  const { currentTheme: theme, variant, styleSlots: styleSlotsProp } = props;
  if (!theme) return {};

  const styleSlots = getStyleSlots<AIMessageProps["styleSlots"]>(
    messageComponentName,
    theme,
    variant,
    styleSlotsProp,
  );

  return {
    display: "flex",
    flexDirection: "column",
    gap: theme.toRem(theme.spacing[16]),
    maxWidth: "100%",
    padding: `0 ${theme.toRem(theme.spacing[8])}`,

    [`&.${AIMessageClasses.messageUser}`]: {
      alignSelf: "flex-end",
      backgroundColor: theme.color.background.strong,
      color: theme.color.content.strong,
      padding: theme.toRem(theme.spacing[8]),
      marginInlineEnd: theme.toRem(theme.spacing[8]),
      borderRadius: theme.border.radius.sm,
      maxWidth: "80%",
      ...styleSlots?.messageUser,
    },
    [`&.${AIMessageClasses.messageAssistant}`]: {
      alignSelf: "flex-start",
      width: "100%",
      ...styleSlots?.messageAssistant,
    },

    // Plain Text Content
    [`.${AIMessageClasses.plainText}`]: {
      ...theme.typography.body.md,
      whiteSpace: "pre-wrap",
      ...styleSlots?.plainText,
    },

    // Markdown Content
    [`.${AIMessageClasses.markdown}`]: {
      width: "100%",
      // Reset margins on block elements
      "p, ul, ol, pre, h1, h2, h3, h4, h5, h6": {
        margin: 0,
        padding: 0,
      },
      p: {
        ...theme.typography.body.md,
      },
      "ul, ol": {
        ...theme.typography.body.md,
        paddingLeft: theme.toRem(theme.spacing[24]),
      },
      li: {
        marginBottom: theme.toRem(theme.spacing[4]),
      },
      code: {
        ...theme.typography.code.md,
        backgroundColor: theme.color.background.utility.neutralWeak,
        padding: `${theme.toRem(2)} ${theme.toRem(4)}`,
        borderRadius: theme.toRem(theme.border.radius.none),
        color: theme.color.content.strong,
      },
      pre: {
        backgroundColor: theme.color.background.utility.neutralWeak,
        padding: theme.toRem(theme.spacing[12]),
        borderRadius: theme.toRem(theme.border.radius.sm),
        overflowX: "auto",
        code: {
          backgroundColor: "transparent",
          padding: 0,
          color: "inherit",
        },
      },
      "h1, h2, h3, h4, h5, h6": {
        color: theme.color.content.strong,
      },
      h1: theme.typography.heading.lg,
      h2: theme.typography.heading.md,
      h3: theme.typography.heading.sm,

      // Spacing (Owl Selector)
      "& > * + *": {
        marginTop: theme.toRem(theme.spacing[12]),
      },
      ...styleSlots?.markdown,
    },
    ...styleSlots?.root,
  };
};

const excludedMessageDOMProps = [...getExcludedDOMProps(), "role", "plainText"];

export const StyledAIMessage = styled("div", {
  shouldForwardProp: (prop) => !excludedMessageDOMProps.includes(prop),
})<AIMessageProps>((props) => generateMessageStyles(props));

// --- AIMessageList ---

const messageListComponentName = "AIMessageList";

export const AIMessageListClasses = {
  root: "exp-textura_ai_message_list",
};

const generateMessageListStyles = (props: AIMessageListProps): CSSObject => {
  const { currentTheme: theme, variant, styleSlots: styleSlotsProp } = props;
  if (!theme) return {};

  const styleSlots = getStyleSlots<AIMessageListProps["styleSlots"]>(
    messageListComponentName,
    theme,
    variant,
    styleSlotsProp,
  );

  return {
    flex: 1,
    overflowY: "auto",
    display: "flex",
    flexDirection: "column",
    gap: theme.toRem(theme.spacing[16]),
    padding: `${theme.toRem(theme.spacing[16])} ${theme.toRem(theme.spacing[8])}`,

    // Hide scrollbar but allow scrolling
    scrollbarWidth: "none", // Firefox
    msOverflowStyle: "none", // IE and Edge
    "&::-webkit-scrollbar": {
      display: "none", // Chrome, Safari and Opera
    },

    ...styleSlots?.root,
  };
};

const excludedMessageListDOMProps = getExcludedDOMProps();

export const StyledAIMessageList = styled("div", {
  shouldForwardProp: (prop) => !excludedMessageListDOMProps.includes(prop),
})<AIMessageListProps>((props) => generateMessageListStyles(props));
